var areSimilar = function(mat, k) {
    const m = mat.length, n = mat[0].length;
    k %= n;
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (mat[i][j] !== mat[i][(j + k) % n]) return false;
        }
    }
    return true;
};
